async function executeTransactionQuery(subgraph, query, variables) {
  try {
    const data = await fetchFromSubgraph(subgraph, {
      query,
      variables,
      requestId: "useAbstractTokenTransactions"
    });
    return { data: data || {}, error: false };
  } catch (e) {
    console.error("Failed to fetch from subgraph:", e);
    return { error: true };
  }
}
function transformV2(tx) {
  let token0Quantity;
  let token1Quantity;
  let account;
  token0Quantity = tx.amount0In !== "0" ? tx.amount0In : `-${tx.amount0Out}`;
  token1Quantity = tx.amount1In !== "0" ? tx.amount1In : `-${tx.amount1Out}`;
  account = tx.sender;
  return {
    id: tx.id,
    type: "Swap",
    timestamp: tx.timestamp,
    hash: tx.transaction.id,
    blockNumber: tx.transaction.blockNumber,
    account,
    token0: tx.pair.token0,
    token1: tx.pair.token1,
    token0Quantity,
    token1Quantity,
    usdValue: { value: parseFloat(tx.amountUSD || "0") }
  };
}
function transformV3(tx) {
  let token0Quantity;
  let token1Quantity;
  let account;
  token0Quantity = tx.amount0;
  token1Quantity = tx.amount1;
  account = tx.sender;
  return {
    id: tx.id,
    type: "Swap",
    timestamp: tx.timestamp,
    hash: tx.transaction.id,
    blockNumber: tx.transaction.blockNumber,
    account,
    token0: tx.pool.token0,
    token1: tx.pool.token1,
    token0Quantity,
    token1Quantity,
    usdValue: { value: parseFloat(tx.amountUSD || "0") }
  };
}
export function useAbstractTokenTransactions(tokenAddress, chainId, _filter = [TokenTransactionType.BUY, TokenTransactionType.SELL]) {
  const pageSize = 75;
  const enabled = Boolean(tokenAddress && chainId);
  const query = useQuery({
    queryKey: ["abstract-token-transactions", tokenAddress.toLowerCase(), chainId, _filter, pageSize],
    enabled,
    refetchInterval: 3e4,
    queryFn: async () => {
      const subgraphs = getAbstractSubgraphs(chainId);
      const lower = tokenAddress.toLowerCase();
      const vars = { first: pageSize, skip: 0, token: lower };
      const results = [];
      const [v2Response, v3Response] = await Promise.all([
        executeTransactionQuery(subgraphs.v2, V2_TOKEN_SWAPS, vars),
        executeTransactionQuery(subgraphs.v3, V3_TOKEN_SWAPS, vars)
      ]);
      if (!v2Response.error && v2Response.data?.swaps) {
        results.push(...v2Response.data.swaps.map((s) => transformV2(s)));
      }
      if (!v3Response.error && v3Response.data?.swaps) {
        results.push(...v3Response.data.swaps.map((s) => transformV3(s)));
      }
      return {
        transactions: results.sort((a, b) => parseInt(b.timestamp) - parseInt(a.timestamp)),
        errorV2: v2Response.error,
        errorV3: v3Response.error
      };
    }
  });
  return {
    transactions: query.data?.transactions ?? [],
    loading: query.isLoading,
    errorV2: query.data?.errorV2 ?? false,
    errorV3: query.data?.errorV3 ?? false,
    loadMore: void 0
  };
}
